                raise TypeError(f"{row_where} must be a dict")
            if tuple(row.keys()) != _EVOLUTION_GROUP_COMPARISONS_ROW_KEYS:
                raise ValueError(
                    f"{row_where} must have exactly the keys group, "
                    "scenario, count, mean, slope, uncertainty, band in "
                    "order"
                )

