            row["coverage"], f"{row_where}.coverage", nullable=False
        )
        if not 0 <= row["coverage"] <= 1:
            raise ValueError(
                f"{row_where}.coverage must be between 0 and 1"
            )
        if row["coverage"] != round(valid / total, 12):
            raise ValueError(
                f"{row_where}.coverage must equal round(valid / total, 12)"
            )

        mean = row["mean"]
        std = row["std"]
        uncertainty = row["uncertainty"]
        rank = row["rank"]
        if rank is not None and (
            not isinstance(rank, int) or isinstance(rank, bool)
        ):
            raise TypeError(
                f"{row_where}.rank must be a non-bool int or None"
            )
        if rank is None:
            null_phase = True
            if mean is not None or std is not None or uncertainty is not None:
                raise ValueError(
                    f"{row_where}: mean, std and uncertainty must be None "
                    "when rank is None"
                )
            if order <= invalid_order:
                raise ValueError(
                    f"{row_where}: unranked rows must keep the original "
                    "group order"
                )
            invalid_order = order
        else:
            if null_phase:
                raise ValueError(
                    f"{row_where}: ranked rows must precede rows with "
                    "rank None"
                )
            if mean is None or std is None or uncertainty is None:
                raise ValueError(
                    f"{row_where}: mean, std and uncertainty must all be "
                    "present when rank is not None"
                )
            if valid < 1:
                raise ValueError(
                    f"{row_where}.valid must be positive when rank is not "
                    "None"
                )
            valid_count += 1
            if rank != valid_count:
                raise ValueError(
                    f"{row_where}.rank must run consecutively from 1"
                )
            _validate_number(mean, f"{row_where}.mean", nullable=False)
            _validate_number(std, f"{row_where}.std", nullable=False)
            _validate_number(
                uncertainty, f"{row_where}.uncertainty", nullable=False
            )
            if std < 0:
                raise ValueError(f"{row_where}.std must be non-negative")
            if uncertainty < 0:
                raise ValueError(
                    f"{row_where}.uncertainty must be non-negative"
                )

    return reference, groups, scenarios, data


def group_scale(items, *, minimum: int = 1) -> dict:
    """Aggregate group rank stability across named scales and regions.

    ``items`` must be a non-empty list of mappings, each with exactly
    the keys ``scale, region, result`` in that order.  ``scale`` and
    ``region`` are non-empty str values and every ``(scale, region)``
    pair must be unique; ``result`` is a complete
    :func:`group_rank_stability` result (schema
    ``climate-grid/ggs-v1``), with every member validated against that
    contract.  Every result must share the same ``reference`` and the
    same ``groups`` and ``scenarios`` axes in the same order, taken
    from the first item.  ``minimum`` must be a non-bool positive
    int.

    For each group (in group order) the group's row is taken from
    every result; ``total`` is the number of items and ``valid`` is
    the number of those rows whose ``rank`` is not ``None``, with
    ``coverage = valid / total``.  When ``valid < minimum``, ``mean``,
    ``std``, ``uncertainty`` and ``rank`` are all ``None``; otherwise
    ``mean`` is the mean of the rows' ``mean`` values, ``std`` is the
    population standard deviation of those values and
    ``uncertainty`` is the ``hypot`` of every valid row's
    ``uncertainty`` divided by ``valid``.

    The valid groups are ranked, from 1, by their unrounded ``mean``
    in ascending order; ties keep the group order.  Invalid groups
    follow in their original group order with ``rank`` of ``None``.

    The returned mapping uses the key order ``schema, scales,
    regions, reference, groups, scenarios, data``; ``schema`` is
    ``climate-grid/ggs-scale-v1``, ``scales`` and ``regions`` list
    the item names in first-appearance order and ``reference``,
    ``groups`` and ``scenarios`` echo the first item's result
    unchanged.  ``data`` follows the ranking above; each row uses the
    key order ``group, total, valid, coverage, mean, std,
    uncertainty, rank``.  ``total`` and ``valid`` are ints and
    ``rank`` is an int or ``None``; every output float is
    ``round(x, 12)`` with negative zero normalized to ``0.0`` and a
    non-finite derived value raises ``ValueError``.  The input is not
    modified.

    Raises ``TypeError`` for wrong container/item/argument types and
    ``ValueError`` for any other contract violation.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if len(items) < 1:
        raise ValueError("items must be non-empty")

    scales: list[str] = []
    regions: list[str] = []
    seen_scales: set[str] = set()
    seen_regions: set[str] = set()
    seen_pairs: set[tuple[str, str]] = set()
    validated: list[dict[str, dict]] = []
    reference = ""
    groups: list[str] = []
    scenarios: list[str] = []
    for index, item in enumerate(items):
        where = f"items[{index}]"
        if not isinstance(item, dict):
            raise TypeError(f"{where} must be a dict")
        if tuple(item.keys()) != _GROUP_SCALE_ITEM_KEYS:
            raise ValueError(
                f"{where} must have exactly the keys scale, region, result "
                "in order"
            )

        scale = item["scale"]
        if not isinstance(scale, str):
            raise TypeError(f"{where}.scale must be a str")
        if scale == "":
            raise ValueError(f"{where}.scale must be non-empty")

        region = item["region"]
        if not isinstance(region, str):
            raise TypeError(f"{where}.region must be a str")
        if region == "":
            raise ValueError(f"{where}.region must be non-empty")

        pair = (scale, region)
        if pair in seen_pairs:
            raise ValueError(
                f"duplicate items scale/region pair: "
                f"({scale!r}, {region!r})"
            )
        seen_pairs.add(pair)
        if scale not in seen_scales:
            seen_scales.add(scale)
            scales.append(scale)
        if region not in seen_regions:
            seen_regions.add(region)
            regions.append(region)

        item_reference, item_groups, item_scenarios, data = (
            _validate_group_rank_stability_result(
                item["result"], where=f"{where}.result"
            )
        )
        if not validated:
            reference = item_reference
            groups = item_groups
            scenarios = item_scenarios
        else:
            if item_reference != reference:
                raise ValueError(
                    "all items must share the same result reference, taken "
                    "from the first item"
                )
            if item_groups != groups:
                raise ValueError(
                    "all items must share the same result groups in the "
                    "same order, taken from the first item"
                )
            if item_scenarios != scenarios:
                raise ValueError(
                    "all items must share the same result scenarios in the "
                    "same order, taken from the first item"
                )

        validated.append({row["group"]: row for row in data})

    if not isinstance(minimum, int) or isinstance(minimum, bool):
        raise TypeError("minimum must be a non-bool int")
    if minimum < 1:
        raise ValueError("minimum must be positive")

    total = len(items)
    valid_rows: list[dict] = []
    invalid_rows: list[dict] = []
    for group in groups:
        means: list[float] = []
        uncertainties: list[float] = []
        for rows in validated:
            row = rows[group]
            if row["rank"] is not None:
                means.append(float(row["mean"]))
                uncertainties.append(float(row["uncertainty"]))

        valid = len(means)
        base_row = {
            "group": group,
            "total": total,
            "valid": valid,
            "coverage": _round_output(valid / total),
        }
        if valid < minimum:
            invalid_rows.append(
                {
                    **base_row,
                    "mean": None,
                    "std": None,
                    "uncertainty": None,
                    "rank": None,
                }
            )
            continue

        mean_value = sum(means) / valid
        variance = sum((value - mean_value) ** 2 for value in means) / valid
        std_value = math.sqrt(variance)
        try:
            uncertainty_value = math.hypot(*uncertainties) / valid
        except OverflowError:
            raise ValueError(
                f"derived statistics for group {group!r} must be finite"
            ) from None

        if (
            not _is_finite(mean_value)
            or not _is_finite(std_value)
            or not _is_finite(uncertainty_value)
        ):
            raise ValueError(
                f"derived statistics for group {group!r} must be finite"
            )

        valid_rows.append(
            {
                **base_row,
                "mean_value": mean_value,
                "mean": _round_output(mean_value),
                "std": _round_output(std_value),
                "uncertainty": _round_output(uncertainty_value),
            }
        )

    valid_rows.sort(key=lambda row: row["mean_value"])
    data_rows = []
    for rank, row in enumerate(valid_rows, start=1):
        data_rows.append(
            {
                "group": row["group"],
                "total": row["total"],
                "valid": row["valid"],
                "coverage": row["coverage"],
                "mean": row["mean"],
                "std": row["std"],
                "uncertainty": row["uncertainty"],
                "rank": rank,
            }
        )
    for row in invalid_rows:
        data_rows.append(row)

    return {
        "schema": _GROUP_SCALE_SCHEMA,
        "scales": scales,
        "regions": regions,
        "reference": reference,
        "groups": list(groups),
        "scenarios": list(scenarios),
        "data": data_rows,
    }
